/* Generated by CraftyEnterprises/ecosystem/sync.mjs. Do not edit here: change the hub copy and re-run the sync. */
/* Crafty bar: the shared ecosystem layer for every Crafty web app.
   Source of truth: CraftyEnterprises/ecosystem/web. Copied into each app by
   ecosystem/sync.mjs, together with crafty-catalog.js and crafty-bar.css.

   Crafty.init({ app: 'works' })   once, after crafty-catalog.js has loaded
   Crafty.open()                   show the Crafty apps panel
   Crafty.event('building.built', uniqueId)   report something the catalogue rewards

   No dependencies, no inline styles (works under a strict Content-Security-Policy),
   and nothing touches the network unless the app uses accounts and the player has
   connected it to their Crafty account. */
(function () {
  'use strict';

  var cfg = null;      // { app, host, catalog, hub, hubSession }
  var panel = null;
  var me = null;
  var lastError = '';

  var store = {
    get: function (k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set: function (k, v) { try { if (v == null) localStorage.removeItem(k); else localStorage.setItem(k, v); } catch (e) { /* private mode */ } },
  };
  var key = function (name) { return 'crafty.' + cfg.app + '.' + name; };

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }

  /* ---------------------------------------------------------- catalogue -- */

  // Same rule as the hub (server/ecosystem.js visibleTo): who an app is for, and
  // which topics the host app must never show.
  function visibleApps() {
    var host = cfg.host;
    return cfg.catalog.apps.filter(function (a) {
      return a.id !== host.id
        && host.sees.audiences.indexOf(a.audience) >= 0
        && !a.topics.some(function (t) { return host.sees.hideTopics.indexOf(t) >= 0; });
    });
  }

  function hubUrl() {
    if (cfg.hubSession) return location.origin;
    var url = cfg.hub || (cfg.catalog.hub && cfg.catalog.hub.url);
    return url ? String(url).replace(/\/+$/, '') : null;
  }

  // Inside a Crafty Android wrapper (its user agent carries "CraftyApp/"), Android apps
  // open through an intent: link the wrapper hands to the system.
  var inAndroidApp = /\bCraftyApp\//.test(navigator.userAgent || '');

  function appLink(app) {
    if (inAndroidApp && app.android) {
      return 'intent:#Intent;action=android.intent.action.MAIN;category=android.intent.category.LAUNCHER;package=' + app.android + ';end';
    }
    if (!app.web) return null;
    if (/^https?:\/\//.test(app.web)) return app.web;
    var hub = hubUrl();
    return hub ? hub + app.web : null;
  }

  /* ------------------------------------------------------------ account -- */

  var accountsOn = function () { return Boolean(cfg.host.accounts && hubUrl()); };
  var token = function () { return cfg.hubSession ? cfg.hubSession() : store.get(key('token')); };

  function api(method, route, body) {
    var t = token();
    return fetch(hubUrl() + '/api/ecosystem/' + route, {
      method: method,
      headers: Object.assign({}, t ? { authorization: 'Bearer ' + t } : {}, body ? { 'content-type': 'application/json' } : {}),
      body: body ? JSON.stringify(body) : undefined,
    }).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (data) {
        if (res.status === 401 && !cfg.hubSession) { store.set(key('token'), null); me = null; }
        data.status = res.status;
        return data;
      });
    });
  }

  // The hub sends the player back here with #crafty_token=…&crafty_name=… after /connect.
  function takeTokenFromUrl() {
    if (!location.hash || location.hash.indexOf('crafty_token=') < 0) return;
    var params = new URLSearchParams(location.hash.slice(1));
    var t = params.get('crafty_token');
    if (/^[0-9a-f]{64}$/.test(t || '')) {
      store.set(key('token'), t);
      store.set(key('name'), params.get('crafty_name'));
    }
    params.delete('crafty_token'); params.delete('crafty_name');
    var rest = params.toString();
    try { history.replaceState(null, '', location.pathname + location.search + (rest ? '#' + rest : '')); } catch (e) { location.hash = rest; }
    cfg.justConnected = true;
  }

  function connect() {
    var back = location.href.split('#')[0];
    location.href = hubUrl() + '/connect.html?app=' + encodeURIComponent(cfg.app) + '&return=' + encodeURIComponent(back);
  }

  function disconnect() {
    var done = function () { store.set(key('token'), null); store.set(key('name'), null); me = null; render(); };
    api('POST', 'unlink', {}).then(done, done);
  }

  function refresh() {
    if (!accountsOn() || !token()) return Promise.resolve(null);
    return api('GET', 'me').then(function (r) {
      lastError = '';
      if (r.ok) { me = r.me; me.connected = r.connected || null; }
      render();
      return me;
    }, function () { lastError = 'Offline: Crafty will catch up when you reconnect.'; render(); return null; });
  }

  /* ------------------------------------------------------------- events -- */

  // Events wait in a queue until they reach the hub, so a chore ticked offline still counts.
  // Each carries an id, and the hub pays an id only once.
  function queue() { try { return JSON.parse(store.get(key('queue')) || '[]'); } catch (e) { return []; } }
  function saveQueue(q) { store.set(key('queue'), q.length ? JSON.stringify(q.slice(-50)) : null); }

  function flush() {
    if (!accountsOn() || !token()) return Promise.resolve();
    var q = queue();
    if (!q.length) return Promise.resolve();
    var next = q[0];
    return api('POST', 'event', next).then(function (r) {
      if (r.status === 429) return;
      saveQueue(queue().filter(function (e) { return e.id !== next.id; }));
      if (r.awarded) { toast('+' + r.awarded + ' Crafty credits'); if (r.me) { me = Object.assign(me || {}, r.me); render(); } }
      return flush();
    }, function () { /* offline: try again later */ });
  }

  function event(type, id) {
    var rewards = cfg && cfg.host.rewards;
    if (!rewards || !Object.prototype.hasOwnProperty.call(rewards, type)) return Promise.resolve(null);
    if (!accountsOn() || !token()) return Promise.resolve(null);
    var q = queue();
    var eid = String(id || (type + ':' + Date.now() + ':' + Math.random().toString(36).slice(2, 8))).slice(0, 64);
    if (!q.some(function (e) { return e.id === eid; })) q.push({ type: type, id: eid });
    saveQueue(q);
    return flush();
  }

  /* ----------------------------------------------------------------- UI -- */

  function toast(text) {
    var t = el('div', 'crafty-toast', text);
    t.setAttribute('role', 'status');
    document.body.appendChild(t);
    setTimeout(function () { t.classList.add('crafty-out'); }, 2200);
    setTimeout(function () { t.remove(); }, 2700);
  }

  function badge(app) {
    if (app.audience === 'adult') return el('span', 'crafty-badge crafty-adult', '18+');
    if (app.audience === 'kids') return el('span', 'crafty-badge crafty-kids', 'For kids');
    return null;
  }

  function accountBlock() {
    var box = el('div', 'crafty-account');
    if (!cfg.host.accounts) {
      box.appendChild(el('p', 'crafty-muted', cfg.host.privacy || 'This app works without an account.'));
      return box;
    }
    if (!hubUrl()) {
      box.appendChild(el('p', 'crafty-muted', 'Crafty accounts switch on once Crafty Enterprises is online.'));
      return box;
    }
    if (!token()) {
      box.appendChild(el('p', 'crafty-strong', 'One account for every Crafty app'));
      var perks = Object.keys(cfg.host.rewards || {}).map(function (k) { var r = cfg.host.rewards[k]; return r.label.toLowerCase() + ': +' + r.credits + ' credits'; });
      box.appendChild(el('p', 'crafty-muted', perks.length
        ? 'Earn Crafty credits here (' + perks.join(', ') + ') and spend them in every Crafty game.'
        : 'Keep your name and credits across every Crafty app.'));
      var b = el('button', 'crafty-btn crafty-primary', 'Sign in with Crafty');
      b.type = 'button'; b.onclick = connect;
      box.appendChild(b);
      return box;
    }
    var row = el('div', 'crafty-me');
    row.appendChild(el('span', 'crafty-avatar', ((me && me.name) || store.get(key('name')) || 'C').slice(0, 1).toUpperCase()));
    var who = el('div', 'crafty-grow');
    who.appendChild(el('div', 'crafty-strong', (me && me.name) || store.get(key('name')) || 'Signed in'));
    who.appendChild(el('div', 'crafty-muted', me ? Number(me.credits).toLocaleString() + ' Crafty credits' : 'Connecting…'));
    row.appendChild(who);
    box.appendChild(row);
    if (me && me.rewards) {
      Object.keys(me.rewards).forEach(function (k) {
        var r = me.rewards[k];
        box.appendChild(el('p', 'crafty-muted crafty-small', r.label + ': +' + r.credits + ' credits, ' + r.left + ' of ' + r.perDay + ' left today'));
      });
    }
    if (me && me.connected) {
      box.appendChild(el('p', 'crafty-muted crafty-small', me.connected.length
        ? 'Connected apps: ' + me.connected.map(function (c) { var a = cfg.catalog.apps.find(function (x) { return x.id === c.app; }); return a ? a.name : c.app; }).join(', ')
        : 'No other apps connected yet.'));
    }
    if (lastError) box.appendChild(el('p', 'crafty-muted crafty-small', lastError));
    if (!cfg.hubSession) {
      var out = el('button', 'crafty-link', 'Disconnect this app');
      out.type = 'button'; out.onclick = disconnect;
      box.appendChild(out);
    }
    return box;
  }

  function appRow(app) {
    var link = appLink(app);
    var row = el(link ? 'a' : 'div', 'crafty-app');
    if (link) {
      row.href = link;
      // Pages on the hub open in place (out of any frame); other apps get their own tab.
      var onHub = (cfg.hubSession && /^\//.test(app.web || '')) || /^intent:/.test(link);
      row.target = onHub ? (window.top !== window ? '_top' : '_self') : '_blank';
      if (!onHub) row.rel = 'noopener';
    }
    var ic = el('span', 'crafty-icon', app.icon);
    // CSSOM, not a style attribute, so a strict style-src policy still allows it.
    if (app.color) ic.style.setProperty('--crafty-c', app.color);
    row.appendChild(ic);
    var text = el('div', 'crafty-grow');
    var name = el('div', 'crafty-strong', app.name);
    var b = badge(app); if (b) name.appendChild(b);
    text.appendChild(name);
    text.appendChild(el('div', 'crafty-muted', app.tagline));
    row.appendChild(text);
    row.appendChild(el('span', 'crafty-go', link ? 'Open' : app.android ? 'Android' : 'Soon'));
    return row;
  }

  function render() {
    if (!panel || panel.hidden) return;
    var sheet = panel.querySelector('.crafty-sheet');
    while (sheet.firstChild) sheet.removeChild(sheet.firstChild);
    var head = el('div', 'crafty-head');
    head.appendChild(el('span', 'crafty-mark', 'C'));
    var title = el('div', 'crafty-grow');
    title.appendChild(el('div', 'crafty-title', 'Crafty apps'));
    title.appendChild(el('div', 'crafty-muted', 'You are in ' + cfg.host.name));
    head.appendChild(title);
    var x = el('button', 'crafty-close', '×');
    x.type = 'button'; x.setAttribute('aria-label', 'Close'); x.onclick = close;
    head.appendChild(x);
    sheet.appendChild(head);
    sheet.appendChild(accountBlock());
    var list = el('div', 'crafty-list');
    visibleApps().forEach(function (a) { list.appendChild(appRow(a)); });
    sheet.appendChild(list);
  }

  function open() {
    if (!cfg) return;
    if (!panel) {
      panel = el('div', 'crafty-scrim');
      panel.hidden = true;
      var sheet = el('div', 'crafty-sheet');
      sheet.setAttribute('role', 'dialog'); sheet.setAttribute('aria-modal', 'true'); sheet.setAttribute('aria-label', 'Crafty apps');
      sheet.tabIndex = -1;
      panel.appendChild(sheet);
      panel.addEventListener('click', function (e) { if (e.target === panel) close(); });
      document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && panel && !panel.hidden) close(); });
      document.body.appendChild(panel);
    }
    panel.hidden = false;
    render();
    panel.querySelector('.crafty-sheet').focus();
    refresh().then(flush);
  }

  function close() { if (panel) panel.hidden = true; }

  function button(parent) {
    var b = el('button', 'crafty-fab' + (parent ? ' crafty-inline' : ''));
    b.type = 'button';
    b.setAttribute('aria-label', 'Crafty apps');
    b.appendChild(el('span', 'crafty-mark', 'C'));
    b.appendChild(el('span', 'crafty-fab-label', 'Crafty'));
    b.onclick = open;
    (parent || document.body).appendChild(b);
    return b;
  }

  /* --------------------------------------------------------------- init -- */

  function init(options) {
    var catalog = options.catalog || window.CRAFTY_CATALOG;
    var host = catalog && catalog.apps.find(function (a) { return a.id === options.app; });
    if (!host) { if (window.console) console.warn('[crafty] unknown app', options.app); return null; }
    cfg = { app: host.id, host: host, catalog: catalog, hub: options.hub || null, hubSession: options.hubSession || null };
    takeTokenFromUrl();
    if (options.button !== false) button(options.mount || null);
    if (accountsOn() && token()) {
      refresh().then(flush);
      window.addEventListener('online', function () { flush(); });
    }
    if (cfg.justConnected) setTimeout(function () { toast('Connected to Crafty'); open(); }, 300);
    return window.Crafty;
  }

  window.Crafty = {
    init: init,
    open: open,
    close: close,
    event: event,
    apps: function () { return cfg ? visibleApps() : []; },
    get signedIn() { return Boolean(cfg && accountsOn() && token()); },
  };
})();
